INSERT INTO repo_cf_values (cf_value_id, education_level, sub_heading, text, status) VALUES ('CFV_SDG09_SEC_005', 'Secondary education', 'Problem solving and innovation', 'Engage in STEM activities such as building simple prototypes (for example, wind turbines, water filters or smart city models).', 'Active'), ('CFV_SDG09_SEC_006', 'Secondary education', 'Problem solving and innovation', 'Apply systems thinking to explore how innovation can support sustainable development.', 'Active'), ('CFV_SDG09_SEC_007', 'Secondary education', 'Digital and AI engagement', 'Learn basic coding and apply it to practical projects.', 'Active'), ('CFV_SDG09_SEC_008', 'Secondary education', 'Digital and AI engagement', 'Use AI tools to analyse problems and suggest solutions.', 'Active'), ('CFV_SDG09_SEC_009', 'Secondary education', 'Digital and AI engagement', 'Explore generative AI and its applications for creating inclusive, community-based solutions.', 'Active'), ('CFV_SDG09_SEC_010', 'Secondary education', 'Research and inquiry', 'Conduct school or community audits on infrastructure and sustainability.', 'Active'), ('CFV_SDG09_SEC_011', 'Secondary education', 'Research and inquiry', 'Investigate successful case studies (for example, Germany’s green industries or China’s high-speed rail) and assess their transferability.', 'Active'), ('CFV_SDG09_SEC_012', 'Secondary education', 'Research and inquiry', 'Explore the criteria for evaluating sustainable and inclusive industrial practices.', 'Active'), ('CFV_SDG09_SEC_013', 'Secondary education', 'Collaboration and communication', 'Participate in group projects designing sustainable cities or infrastructure.', 'Active'), ('CFV_SDG09_SEC_014', 'Secondary education', 'Collaboration and communication', 'Create awareness posters or multimedia campaigns on innovation and sustainability.', 'Active'), ('CFV_SDG09_SEC_015', 'Secondary education', 'Collaboration and communication', 'Promote dialogue on responsible technology use and equitable access to innovation.', 'Active'), ('CFV_SDG09_TVET_001', 'TVET', 'Commitment to sustainability', 'Intrinsic motivation to support sustainable development through vocational practice.', 'Active'), ('CFV_SDG09_TVET_002', 'TVET', 'Commitment to sustainability', 'Adopt responsible behaviours in trades: reduce waste, conserve energy, use sustainable materials.', 'Active'), ('CFV_SDG09_TVET_003', 'TVET', 'Ethical and inclusive practice', 'Promote fair access to infrastructure and innovation for marginalised and underserved communities.', 'Active'), ('CFV_SDG09_TVET_004', 'TVET', 'Ethical and inclusive practice', 'Uphold social, environmental, and industry standards in all practices.', 'Active'), ('CFV_SDG09_TVET_005', 'TVET', 'Equity and social responsibility', 'Value inclusivity in design and implementation, ensuring accessibility (e.g., for persons with disabilities).', 'Active'), ('CFV_SDG09_TVET_006', 'TVET', 'Equity and social responsibility', 'Appreciate the interdependence between industrial progress and community well-being.', 'Active'), ('CFV_SDG09_TVET_007', 'TVET', 'Entrepreneurial and innovative mindset', 'Demonstrate creativity and critical thinking to solve real-world problems.', 'Active'), ('CFV_SDG09_TVET_008', 'TVET', 'Entrepreneurial and innovative mindset', 'Take initiative to develop eco-friendly enterprises and technical solutions tailored to local challenges.', 'Active'), ('CFV_SDG09_TVET_009', 'TVET', 'Global awareness and cooperation', 'Recognise the importance of international collaboration, knowledge sharing, and technology exchange.', 'Active'), ('CFV_SDG09_TVET_010', 'TVET', 'Global awareness and cooperation', 'Support the greening of industry through partnerships and collective innovation.', 'Active'), ('CFV_SDG09_TVET_011', 'TVET', 'Continuous learning and adaptability', 'Embrace lifelong learning to remain relevant in rapidly evolving industrial fields.', 'Active'), ('CFV_SDG09_TVET_012', 'TVET', 'Continuous learning and adaptability', 'Show willingness to update skills, adopt new technologies, and meet emerging sustainability standards.', 'Active'), ('CFV_SDG09_TER_001', 'Tertiary education', 'Sustainability and ethical responsibility', 'Uphold ethical standards in the development and application of technology and infrastructure.', 'Active'), ('CFV_SDG09_TER_002', 'Tertiary education', 'Sustainability and ethical responsibility', 'Commit to reducing environmental harm, promoting energy efficiency and respecting community rights.', 'Active'), ('CFV_SDG09_TER_003', 'Tertiary education', 'Sustainability and ethical responsibility', 'Advocate for responsible AI development aligned with human values and sustainability.', 'Active'), ('CFV_SDG09_TER_004', 'Tertiary education', 'Inclusivity and social justice', 'Promote equitable access to infrastructure, jobs and innovation – especially in marginalised communities.', 'Active'), ('CFV_SDG09_TER_005', 'Tertiary education', 'Inclusivity and social justice', 'Recognise the global and local impacts of infrastructure choices and advocate for fair distribution of benefits.', 'Active'), ('CFV_SDG09_TER_006', 'Tertiary education', 'Global citizenship and leadership', 'Embrace a global perspective on sustainable development and technological equity.', 'Active'), ('CFV_SDG09_TER_007', 'Tertiary education', 'Global citizenship and leadership', 'Engage in international networks for policy advocacy, knowledge sharing and collaborative research and development (R&D).', 'Active'), ('CFV_SDG09_TER_008', 'Tertiary education', 'Global citizenship and leadership', 'Support policy reform and investment in R&D, especially for underserved regions.', 'Active'), ('CFV_SDG09_TER_009', 'Tertiary education', 'Lifelong learning and adaptability', 'Develop a culture of continuous learning and innovation in response to technological and societal shifts.', 'Active'), ('CFV_SDG09_TER_010', 'Tertiary education', 'Lifelong learning and adaptability', 'Be open to integrating diverse perspectives, including indigenous knowledge, in sustainable solutions.', 'Active'), ('CFV_SDG09_TER_011', 'Tertiary education', 'Proactivity and visionary thinking', 'Lead initiatives that integrate long-term planning with immediate action on sustainability.', 'Active'), ('CFV_SDG09_TER_012', 'Tertiary education', 'Proactivity and visionary thinking', 'Demonstrate vision in balancing technological growth with social and environmental stewardship.', 'Active'), ('CFV_SDG09_ADULT_001', 'Adult education', 'Empowerment and ownership', 'Take initiative in improving community infrastructure and promoting sustainability.', 'Active'), ('CFV_SDG09_ADULT_002', 'Adult education', 'Empowerment and ownership', 'Develop self-confidence and see oneself as a change-maker and contributor to local development.', 'Active'), ('CFV_SDG09_ADULT_003', 'Adult education', 'Equity and inclusion', 'Promote the participation of women, youth and marginalised groups in infrastructure and innovation projects.', 'Active'), ('CFV_SDG09_ADULT_004', 'Adult education', 'Equity and inclusion', 'Advocate for inclusive access to basic services like clean water, energy and transport.', 'Active'), ('CFV_SDG09_ADULT_005', 'Adult education', 'Environmental stewardship', 'Respect and protect the natural environment by conserving resources and reducing pollution.', 'Active'), ('CFV_SDG09_ADULT_006', 'Adult education', 'Environmental stewardship', 'Encourage reuse, recycling and low-impact solutions tailored to local needs.', 'Active'), ('CFV_SDG09_ADULT_007', 'Adult education', 'Community responsibility and leadership', 'Support collective action and shared responsibility in maintaining infrastructure and community assets.', 'Active'), ('CFV_SDG09_ADULT_008', 'Adult education', 'Community responsibility and leadership', 'Mentor or inspire others in the community to take part in development and sustainability activities.', 'Active'), ('CFV_SDG09_ADULT_009', 'Adult education', 'Lifelong learning and adaptability', 'Embrace learning about innovative technologies and approaches that can improve everyday life.', 'Active'), ('CFV_SDG09_ADULT_010', 'Adult education', 'Lifelong learning and adaptability', 'Stay informed and open to innovation and share new knowledge within the community.', 'Active'), ('CFV_SDG10_SEC_001', 'Secondary education', 'Respect, pride and cultural understanding', 'Value and take pride in personal and collective cultural heritage while respecting the traditions of others.', 'Active'), ('CFV_SDG10_SEC_002', 'Secondary education', 'Respect, pride and cultural understanding', 'Appreciate the importance of cultural diversity and recognise how it enriches societies.', 'Active'), ('CFV_SDG10_SEC_003', 'Secondary education', 'Respect, pride and cultural understanding', 'Respect the struggles, contributions and strategies of indigenous and minority groups in shaping inclusive policies.', 'Active'), ('CFV_SDG10_SEC_004', 'Secondary education', 'Empathy, equity and justice', 'Demonstrate empathy towards individuals and groups facing discrimination or exclusion.', 'Active'), ('CFV_SDG10_SEC_005', 'Secondary education', 'Empathy, equity and justice', 'Develop a keen sense of justice and a commitment to equity in personal, school and community life.', 'Active') ON CONFLICT DO NOTHING;